function PracticeSession({syllabusId,subjectId,file,onSave,close}){const[sessionId]=useState(()=>{const key=`degree-study-practice-${syllabusId}`;let id;try{id=localStorage.getItem(key);if(!id){id=uid();localStorage.setItem(key,id)}}catch{id=uid()}return id}),[fileId,setFileId]=useState(file?.id||null),[fileName,setFileName]=useState(file?.fileName||"main.py"),[storedFileName,setStoredFileName]=useState(file?.fileName||null),[code,setCode]=useState(""),[command,setCommand]=useState(""),[cwd,setCwd]=useState("Connecting to local PowerShell…"),[entries,setEntries]=useState([]),[ready,setReady]=useState(false),[busy,setBusy]=useState(false),[runJobId,setRunJobId]=useState(null);
 useEffect(()=>{let cancelled=false;(async()=>{try{const response=await apiFetch("/api/practice",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"init",sessionId})}),result=await response.json();if(!response.ok)throw new Error(result.error||"Unable to start the practice workspace.");if(result.practiceApiVersion!==4)throw new Error("The practice runner is out of date. Close all Degree Study Manager windows and restart the app to update it.");if(cancelled)return;setCwd(result.cwd);setReady(true);setEntries([{id:uid(),kind:"system",text:`Practice workspace ready for this syllabus.\n${result.cwd}\nCommands run as your Windows account.`}])}catch(error){if(!cancelled)setEntries([{id:uid(),kind:"error",text:error instanceof Error?error.message:"Unable to start the practice workspace."}])}})();return()=>{cancelled=true}},[sessionId]);
 useEffect(()=>{let cancelled=false;if(!file){setFileId(null);setFileName("main.py");setStoredFileName(null);setCode("");return()=>{cancelled=true}}const savedName=file.fileName||"main.py";setFileId(file.id);setFileName(savedName);setStoredFileName(savedName);fetch(file.dataUrl).then(response=>{if(!response.ok)throw new Error("Saved practice file could not be read.");return response.text()}).then(async text=>{if(cancelled)return;setCode(text);if(new Blob([text]).size>2*1024*1024)return;const response=await apiFetch("/api/practice",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"save",sessionId,fileName:savedName,code:text})}),result=await response.json();if(!response.ok)throw new Error(result.error||"Unable to sync the saved file to the practice workspace.");if(!cancelled)setCwd(result.cwd||cwd)}).catch(error=>{if(!cancelled)setEntries(current=>[...current,{id:uid(),kind:"error",text:error instanceof Error?error.message:"Saved practice file could not be synced."}])});return()=>{cancelled=true}},[file]);
 function logError(error){setEntries(current=>[...current,{id:uid(),kind:"error",text:error instanceof Error?error.message:"Practice action failed."}].slice(-100))}
 async function execute(action,payload={}){if(!ready||busy)return;setBusy(true);setEntries(current=>[...current,{id:uid(),kind:"command",text:action==="run"?`Run ${payload.fileName}`:`PS> ${payload.command}`}].slice(-100));try{const response=await apiFetch("/api/practice",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action,sessionId,...payload})}),result=await response.json();if(!response.ok)throw new Error(result.error||"Practice command failed.");setCwd(result.cwd||cwd);const text=[result.output||"(No output)",`[exit code ${result.exitCode}]`].join("\n");setEntries(current=>[...current,{id:uid(),kind:result.ok?"output":"error",text}].slice(-100))}catch(error){logError(error)}finally{setBusy(false)}}
 async function pollRun(jobId){try{while(true){await new Promise(resolve=>setTimeout(resolve,250));const response=await apiFetch("/api/practice",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"poll",sessionId,jobId})}),result=await response.json();if(!response.ok)throw new Error(result.error||"Unable to read program output.");if(result.output)setEntries(current=>[...current,{id:uid(),kind:result.done&&!result.ok?"error":"output",text:result.output}].slice(-100));if(result.done){setCwd(result.cwd||cwd);const status=[`[exit code ${result.exitCode}]`,result.timedOut?"[Program timed out after 30 seconds.]":null,result.truncated?"[Output truncated after 1 MB.]":null].filter(Boolean).join("\n");setEntries(current=>[...current,{id:uid(),kind:result.ok?"system":"error",text:status}].slice(-100));setRunJobId(null);return}}}catch(error){setRunJobId(null);logError(error)}}
 async function runCode(){const name=fileName.trim();if(!/^[^<>:"/\\|?*\u0000-\u001f]+\.[A-Za-z0-9]+$/.test(name)||name.endsWith(".")||name.endsWith(" "))return logError(new Error("Enter a valid file name with a programming-language extension, such as main.py."));if(!ready||busy||runJobId)return;setBusy(true);setEntries(current=>[...current,{id:uid(),kind:"command",text:`Run ${name}`}].slice(-100));try{const response=await apiFetch("/api/practice",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"run",sessionId,fileName:name,code})}),result=await response.json();if(!response.ok)throw new Error(result.error||"Program failed to start.");setCwd(result.cwd||cwd);setRunJobId(result.jobId);void pollRun(result.jobId)}catch(error){logError(error)}finally{setBusy(false)}}
 function runCommand(event){event.preventDefault();const value=command;if(!value&&!runJobId)return;setCommand("");if(runJobId){apiFetch("/api/practice",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"input",sessionId,jobId:runJobId,input:value})}).then(async response=>{const result=await response.json();if(!response.ok)throw new Error(result.error||"Unable to send input to the running program.");setEntries(current=>[...current,{id:uid(),kind:"command",text:value}].slice(-100))}).catch(logError);return}const trimmed=value.trim();if(trimmed)execute("command",{command:trimmed})}
 async function saveFile(){const name=fileName.trim();if(!/^[^<>:"/\\|?*\u0000-\u001f]+\.[A-Za-z0-9]+$/.test(name)||name.endsWith(".")||name.endsWith(" "))return logError(new Error("Enter a valid file name with an extension, such as main.py."));if(new Blob([code]).size>2*1024*1024)return logError(new Error("Practice files must be 2 MB or smaller."));try{const response=await apiFetch("/api/practice",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"save",sessionId,fileName:name,code,previousFileName:fileId&&storedFileName!==name?storedFileName:undefined})}),result=await response.json();if(!response.ok)throw new Error(result.error||"Unable to sync the practice file to the workspace.");const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>typeof reader.result==="string"?resolve(reader.result):reject(new Error("Could not encode the practice file."));reader.onerror=()=>reject(new Error("Could not encode the practice file."));reader.readAsDataURL(new Blob([code],{type:"text/plain"}))});const savedId=onSave({syllabusId,subjectId,fileId,fileName:name,dataUrl,size:new Blob([code]).size});setFileId(savedId);setStoredFileName(name);setCwd(result.cwd||cwd);setEntries(current=>[...current,{id:uid(),kind:"system",text:`Saved ${name} to this syllabus and practice workspace.`}].slice(-100))}catch(error){logError(error)}}
 function editCode(event){const target=event.currentTarget,start=target.selectionStart,end=target.selectionEnd;if(event.key==="Enter"&&(event.ctrlKey||event.metaKey)){event.preventDefault();runCode();return}if(event.key==="Enter"){event.preventDefault();const lineStart=code.lastIndexOf("\n",start-1)+1,indent=/^[ \t]*/.exec(code.slice(lineStart,start))?.[0]||"",next=code.slice(0,start)+"\n"+indent+code.slice(end),caret=start+1+indent.length;setCode(next);requestAnimationFrame(()=>target.setSelectionRange(caret,caret));return}if(event.key!=="Tab")return;event.preventDefault();const selected=code.slice(start,end),lineStart=code.lastIndexOf("\n",start-1)+1;if(event.shiftKey){const remove=selected?selected.replace(/(^|\n)(?: {1,4}|\t)/g,"$1"):code.slice(lineStart).match(/^(?: {1,4}|\t)/)?.[0]||"";if(!remove)return;const next=selected?code.slice(0,start)+remove+code.slice(end):code.slice(0,lineStart)+code.slice(lineStart+remove.length);setCode(next);const caret=start-(selected?0:remove.length);requestAnimationFrame(()=>target.setSelectionRange(caret,caret));return}if(selected.includes("\n")){const indented=selected.replace(/^/gm,"    ");setCode(code.slice(0,start)+indented+code.slice(end));requestAnimationFrame(()=>target.setSelectionRange(start,start+indented.length));return}const next=code.slice(0,start)+"    "+code.slice(end);setCode(next);requestAnimationFrame(()=>target.setSelectionRange(start+4,start+4))}
 return <div className="practice-overlay"><div className="practice-window"><header className="practice-header"><div className="practice-title"><Code2/><div><h2>Syllabus practice</h2><small>Code is saved with this syllabus</small></div></div><Button type="button" variant="translucent" onClick={close}><X/>Close</Button></header><div className="practice-toolbar"><label className="practice-filename-label">File name <Input aria-label="Program file name" value={fileName} onChange={event=>setFileName(event.target.value)} placeholder="main.py"/></label><Button type="button" variant="outline" onClick={saveFile} disabled={!ready||busy||!!runJobId}><Save/>{fileId?"Save / rename":"Save to syllabus"}</Button><Button type="button" onClick={runCode} disabled={!ready||busy||!!runJobId}><Play/>{busy?"Starting…":runJobId?"Program running…":"Run file"}</Button><span className="practice-cwd" title={cwd}>Working directory: {cwd}</span></div><div className="practice-workspace"><section className="practice-editor-panel"><div className="practice-panel-heading"><Code2/>{fileName||"Untitled"}<span>Tab / Shift+Tab indent · Ctrl+Enter to run</span></div><textarea className="practice-editor" aria-label="Practice code editor" spellCheck="false" value={code} onChange={event=>setCode(event.target.value)} onKeyDown={editCode}/></section><section className="practice-terminal-panel"><div className="practice-panel-heading"><Terminal/>{runJobId?"Program input / terminal":"PowerShell terminal"} <button type="button" onClick={()=>setEntries([])}>Clear</button></div><div className="practice-output" aria-live="polite">{entries.map(entry=><pre className={`practice-entry ${entry.kind}`} key={entry.id}>{entry.text}</pre>)}</div><form className="practice-command-form" onSubmit={runCommand}><span>{runJobId?"INPUT&gt;":"PS&gt;"}</span><input aria-label={runJobId?"Program input":"PowerShell command"} autoComplete="off" value={command} onChange={event=>setCommand(event.target.value)} placeholder={runJobId?"Type input and press Enter…":"Enter a PowerShell command…"} disabled={!ready||busy}/><Button type="submit" disabled={!ready||busy||(!runJobId&&!command.trim())}>{runJobId?"Send":"Run"}<Play/></Button></form></section></div><div className="practice-warning"><AlertTriangle/>Programs wait for input in the terminal panel. Commands run as your Windows account and can change files. Each command is limited to 30 seconds and output to 1 MB.</div></div></div>}
function DearFlipViewer({url}){const hostRef=useRef(null),zoomControlRef=useRef(null),[error,setError]=useState(""),[zoomPercent,setZoomPercent]=useState(100);const applyZoom=percent=>{const next=Math.max(100,Math.min(200,Number(percent))),difference=Math.round((next-zoomPercent)/5),button=hostRef.current?.querySelector(difference>=0?".df-ui-zoomin":".df-ui-zoomout");if(button)for(let index=0;index<Math.abs(difference);index++)button.click();setZoomPercent(next)};useEffect(()=>{let active=true;const host=hostRef.current;let observer;(async()=>{try{await loadDearFlip();if(!active||!host)return;$(host).flipBook(url,{webgl:true,height:"100%",backgroundColor:"#334155",autoEnableThumbnail:true,autoEnableOutline:true,zoomRatio:1.05});const moveControl=()=>{const controls=host.querySelector(".df-ui-controls");if(controls&&zoomControlRef.current&&!controls.contains(zoomControlRef.current))controls.appendChild(zoomControlRef.current)};observer=new MutationObserver(moveControl);observer.observe(host,{childList:true,subtree:true});moveControl()}catch(error){if(active)setError(error instanceof Error?error.message:"DearFlip could not be opened.")}})();return()=>{active=false;observer?.disconnect();host?.replaceChildren()}},[url]);if(error)return <div className="attachment-file-message"><strong>{error}</strong><span>Use the normal PDF viewer or download the file instead.</span></div>;return <div className="dearflip-shell"><div ref={hostRef} className="dearflip-host"/><div ref={zoomControlRef} className="dearflip-zoom-control" onClick={event=>event.stopPropagation()}><button type="button" onClick={()=>applyZoom(zoomPercent-5)} disabled={zoomPercent<=100} aria-label="Decrease zoom">−</button><label>Zoom <output>{zoomPercent}%</output><input type="range" min="100" max="200" step="5" value={zoomPercent} onChange={event=>applyZoom(event.target.value)} aria-label="PDF zoom percentage"/></label><button type="button" onClick={()=>applyZoom(zoomPercent+5)} disabled={zoomPercent>=200} aria-label="Increase zoom">+</button><button type="button" className="dearflip-zoom-reset" onClick={()=>applyZoom(100)}>Reset</button></div></div>}
function PdfDocumentPage({document,pageNumber,container,width,zoom,registerPage,onError}){const pageRef=useRef(null),canvasRef=useRef(null),[nearViewport,setNearViewport]=useState(false),[aspectRatio,setAspectRatio]=useState(612/792);useEffect(()=>{const page=pageRef.current;if(!page)return;if(typeof IntersectionObserver==="undefined"){setNearViewport(true);return}const observer=new IntersectionObserver(entries=>setNearViewport(entries[0]?.isIntersecting||false),{root:container,rootMargin:"1100px 0px"});observer.observe(page);return()=>observer.disconnect()},[container,pageNumber]);useEffect(()=>{let cancelled=false,renderTask=null;const canvas=canvasRef.current;if(!nearViewport||!canvas||width<=0)return;document.getPage(pageNumber).then(page=>{if(cancelled)return;const initialViewport=page.getViewport({scale:1}),pageWidth=Math.max(280,width*zoom),viewport=page.getViewport({scale:pageWidth/initialViewport.width}),pixelRatio=Math.min(window.devicePixelRatio||1,1.5),context=canvas.getContext("2d",{alpha:false});if(!context)throw new Error("The browser could not create a PDF page canvas.");setAspectRatio(initialViewport.width/initialViewport.height);canvas.width=Math.ceil(viewport.width*pixelRatio);canvas.height=Math.ceil(viewport.height*pixelRatio);context.fillStyle="#ffffff";context.fillRect(0,0,canvas.width,canvas.height);renderTask=page.render({canvasContext:context,viewport,transform:pixelRatio===1?null:[pixelRatio,0,0,pixelRatio,0,0],background:"rgb(255,255,255)"});return renderTask.promise}).catch(error=>{if(!cancelled&&error?.name!=="RenderingCancelledException")onError(error instanceof Error?error.message:"Unable to render a PDF page.")});return()=>{cancelled=true;renderTask?.cancel();if(canvas){canvas.width=0;canvas.height=0}}},[document,pageNumber,nearViewport,width,zoom,onError]);return <div ref={element=>{pageRef.current=element;registerPage(pageNumber-1,element)}} className="pdf-document-page" style={{aspectRatio,width:Math.max(280,width*zoom)}} aria-label={`Page ${pageNumber}`}><canvas ref={canvasRef}/></div>}
function StandardPdfViewer({url}){const containerRef=useRef(null),pageRefs=useRef([]),loadingTaskRef=useRef(null),[pdfDocument,setPdfDocument]=useState(null),[pageCount,setPageCount]=useState(0),[currentPage,setCurrentPage]=useState(1),[pageWidth,setPageWidth]=useState(0),[zoom,setZoom]=useState(1),[loading,setLoading]=useState(true),[error,setError]=useState("");const reportPageError=React.useCallback(message=>setError(message),[]);useEffect(()=>{let cancelled=false;const controller=new AbortController();setPdfDocument(null);setPageCount(0);setCurrentPage(1);setLoading(true);setError("");(async()=>{try{const pdfjs=await loadPdfJs(),response=await fetch(url,{signal:controller.signal});if(!response.ok)throw new Error("The PDF file could not be read.");const data=new Uint8Array(await response.arrayBuffer());if(cancelled)return;const task=pdfjs.getDocument({data,cMapUrl:`${dearFlipAssetRoot}js/libs/cmaps/`,cMapPacked:true});loadingTaskRef.current=task;const loaded=await task.promise;if(cancelled){await loaded.destroy();return}setPdfDocument(loaded);setPageCount(loaded.numPages)}catch(loadError){if(!cancelled&&loadError?.name!=="AbortError")setError(loadError instanceof Error?loadError.message:"The PDF could not be opened.")}finally{if(!cancelled)setLoading(false)}})();return()=>{cancelled=true;controller.abort();if(loadingTaskRef.current){const task=loadingTaskRef.current;loadingTaskRef.current=null;void task.destroy().catch(()=>{})}}},[url]);useEffect(()=>{const container=containerRef.current;if(!container)return;const updateWidth=()=>setPageWidth(container.clientWidth);updateWidth();if(typeof ResizeObserver==="undefined"){window.addEventListener("resize",updateWidth);return()=>window.removeEventListener("resize",updateWidth)}const observer=new ResizeObserver(updateWidth);observer.observe(container);return()=>observer.disconnect()},[]);useEffect(()=>{const container=containerRef.current;if(!container||!pdfDocument)return;let frame=0;const updateCurrentPage=()=>{const marker=container.getBoundingClientRect().top+64;let nearestPage=1,nearestDistance=Infinity;for(let index=0;index<pageCount;index++){const page=pageRefs.current[index];if(!page)continue;const bounds=page.getBoundingClientRect(),distance=marker<bounds.top?bounds.top-marker:marker>bounds.bottom?marker-bounds.bottom:0;if(distance<nearestDistance){nearestPage=index+1;nearestDistance=distance}}setCurrentPage(nearestPage)};const handleScroll=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(updateCurrentPage)};container.addEventListener("scroll",handleScroll,{passive:true});updateCurrentPage();return()=>{container.removeEventListener("scroll",handleScroll);cancelAnimationFrame(frame)}},[pdfDocument,pageCount]);function jumpToPage(page){const next=Math.max(1,Math.min(pageCount,Number(page)||1));setCurrentPage(next);pageRefs.current[next-1]?.scrollIntoView({behavior:"smooth",block:"start"})}return <div ref={containerRef} className="pdf-standard-scroll" onClick={event=>event.stopPropagation()}><div className="pdf-standard-controls" role="toolbar" aria-label="PDF controls"><div className="pdf-standard-controls-pages"><button type="button" aria-label="Previous page" disabled={loading||!!error||currentPage<=1} onClick={()=>jumpToPage(currentPage-1)}>‹</button><label><input aria-label="Current page" type="number" min="1" max={pageCount||1} disabled={loading||!!error} value={loading?1:currentPage} onChange={event=>jumpToPage(event.target.value)}/><span>of {pageCount||"—"}</span></label><button type="button" aria-label="Next page" disabled={loading||!!error||currentPage>=pageCount} onClick={()=>jumpToPage(currentPage+1)}>›</button></div><div className="pdf-standard-controls-zoom"><button type="button" aria-label="Zoom out" disabled={zoom<=0.5} onClick={()=>setZoom(value=>Math.max(0.5,Math.round((value-0.1)*10)/10))}>−</button><output>{Math.round(zoom*100)}%</output><button type="button" aria-label="Zoom in" disabled={zoom>=2} onClick={()=>setZoom(value=>Math.min(2,Math.round((value+0.1)*10)/10))}>+</button></div></div>{error?<div className="pdf-standard-message" role="alert">{error}<p>Download the file to open it with another PDF viewer.</p></div>:loading?<div className="pdf-standard-message" role="status">Loading PDF…</div>:<div className="pdf-document-pages">{Array.from({length:pageCount},(_,index)=><PdfDocumentPage key={`${url}:${index+1}`} document={pdfDocument} pageNumber={index+1} container={containerRef.current} width={pageWidth} zoom={zoom} registerPage={(page,element)=>{pageRefs.current[page]=element}} onError={reportPageError}/>)}</div>}</div>}
function AttachmentViewer({viewer,close,onOpenWith}){const{note,url,previewText,mode}=viewer;return <div className="attachment-viewer" role="dialog" aria-modal="true" aria-label={`Viewing ${note.title||note.fileName}`} onClick={close}><div className="attachment-viewer-toolbar" onClick={e=>e.stopPropagation()}><div><strong>{note.title||note.fileName}</strong><small>{note.fileName}{mode==="dearflip"?" · DearFlip flipbook":""}</small></div><div className="row"><a className="btn translucent" href={url} download={note.fileName}><Download/><span>Download</span></a><Button variant="translucent" onClick={()=>onOpenWith(note)}><ExternalLink/><span>Open with…</span></Button><Button variant="translucent" aria-label="Close viewer" onClick={close}><X/>Close</Button></div></div><div className={`attachment-viewer-content ${mode==="dearflip"?"dearflip-viewer":note.type==="pdf"?"pdf-viewer":note.type==="image"?"image-viewer":"file-viewer"}`} onClick={e=>e.stopPropagation()}>{mode==="dearflip"?<DearFlipViewer url={url}/>:note.type==="pdf"?<PdfReader key={url} url={url}/>:note.type==="image"?<img className="attachment-image" src={url} alt={note.title||note.fileName}/>:previewText!==null?<pre className="attachment-text">{previewText||"(This file is empty.)"}</pre>:<div className="attachment-file-message"><FileText/><strong>Preview isn’t available for this file.</strong><span>Download it or choose an installed app to open it.</span></div>}</div></div>}
function Dashboard(){}
function TextNotePage({note,item,subject,semester,setView,openModal}){return <><Back label="Back to notes" onClick={()=>setView({type:"syllabus",semesterId:semester?.id,subjectId:subject?.id,syllabusId:note.syllabusId})}/><Card><CardHeader><div className="section-head"><div><small>{subject?.name} · {item?.title}</small><CardTitle>{note.title||"Untitled text note"}</CardTitle><small>Updated {new Date(note.updatedAt||note.createdAt).toLocaleString()}</small></div><Button onClick={()=>openModal("textNote",{...note})}><NotebookPen/>Edit note</Button></div></CardHeader><CardContent><div className="note-view" dangerouslySetInnerHTML={{__html:note.text||""}}/></CardContent></Card></>}
function SettingsPage({degree,scoped,openModal,requestDelete}){return <><Card><CardHeader><CardTitle><Settings/> Settings: {degree.name}</CardTitle></CardHeader><CardContent><div className="warning"><AlertTriangle/><p>This page is scoped to the selected degree.</p></div><div className="row"><Button variant="outline" onClick={()=>openModal("degree",degree)}>Edit degree</Button><Button variant="danger" onClick={()=>requestDelete("degree",degree.id,degree.name)}><Trash2/>Delete degree</Button><Button onClick={()=>openModal("semester",{})}><Plus/>Semester</Button></div></CardContent></Card>{scoped.semesters.map(s=><Card key={s.id}><CardHeader><div className="resource-row"><h3>{s.name}</h3><Button variant="danger" onClick={()=>requestDelete("semester",s.id,s.name)}><Trash2/></Button></div></CardHeader><CardContent>{scoped.subjects.filter(x=>x.semesterId===s.id).map(sub=><div className="settings-row" key={sub.id}><b>{sub.name}</b><Button variant="outline" onClick={()=>openModal("subject",sub)}>Edit</Button><Button variant="danger" onClick={()=>requestDelete("subject",sub.id,sub.name)}><Trash2/></Button></div>)}</CardContent></Card>)}</>}
function Dialog({title,close,children,wide=false}){return <div className="overlay"><Card className={`dialog ${wide?"wide":""}`}><CardHeader><div className="section-head"><CardTitle>{title}</CardTitle><Button variant="ghost" onClick={close}><X/></Button></div></CardHeader><CardContent>{children}</CardContent></Card></div>}
function Field({label,children}){return <label className="field"><Label>{label}</Label>{children}</label>}function Progress({value}){return <div className="progress"><div style={{width:`${value}%`}}/></div>}function Level({value}){return <Badge className={value}>{value}</Badge>}function Back({label,onClick}){return <Button variant="ghost" className="back" onClick={onClick}><ArrowLeft/>{label}</Button>}function Empty({text}){return <Card><CardContent className="empty">{text}</CardContent></Card>}
